package api

import (
	"archive/zip"
	"bytes"
	"fmt"
	"net/http"
	"strings"

	"babo-forever/server/internal/store"
)

const dataAddonTOC = `## Interface: 16001
## Title: Babo Forever - Price Data
## Notes: Generated by Babo Forever. Do not edit by hand.
## Author: babo
## Version: 0.1.0
## X-Category: Auction/Economy

Data.lua
`

func (s *Server) handleDataAddon(w http.ResponseWriter, r *http.Request) {
	market := r.PathValue("market")
	if !marketRE.MatchString(market) {
		writeError(w, http.StatusBadRequest, "invalid market")
		return
	}

	snapshot, err := s.store.Snapshot(r.Context(), market)
	if err != nil {
		if err == store.ErrNotFound {
			writeError(w, http.StatusNotFound, "market not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "snapshot failed")
		return
	}

	data := buildDataLua(snapshot)
	var buf bytes.Buffer
	zw := zip.NewWriter(&buf)
	if err := addZipFile(zw, "BaboForever_Data/BaboForever_Data.toc", dataAddonTOC); err != nil {
		writeError(w, http.StatusInternalServerError, "zip failed")
		return
	}
	if err := addZipFile(zw, "BaboForever_Data/Data.lua", data); err != nil {
		writeError(w, http.StatusInternalServerError, "zip failed")
		return
	}
	if err := zw.Close(); err != nil {
		writeError(w, http.StatusInternalServerError, "zip failed")
		return
	}

	filename := "BaboForever_Data-" + strings.ReplaceAll(market, ":", "_") + ".zip"
	w.Header().Set("Content-Type", "application/zip")
	w.Header().Set("Content-Disposition", `attachment; filename="`+filename+`"`)
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(buf.Bytes())
}

func addZipFile(zw *zip.Writer, name, content string) error {
	entry, err := zw.Create(name)
	if err != nil {
		return err
	}
	_, err = entry.Write([]byte(content))
	return err
}

func buildDataLua(snapshot store.Snapshot) string {
	var b strings.Builder
	b.WriteString("-- Generated by Babo Forever. Do not edit by hand.\n")
	b.WriteString("BABOFOREVER_DATA = {\n")
	b.WriteString("  schema = 1,\n")
	b.WriteString("  markets = {\n")
	fmt.Fprintf(&b, "    [%q] = {\n", snapshot.Market)
	fmt.Fprintf(&b, "      version = %d,\n", snapshot.Version)
	fmt.Fprintf(&b, "      generated = %d,\n", snapshot.Generated)
	b.WriteString("      items = {\n")
	for _, item := range snapshot.Items {
		fmt.Fprintf(&b, "        { k = %q, p = %d, q = %d, n = %d, t = %d },\n",
			item.Key, item.Price, item.Quantity, item.Listings, item.Scanned)
	}
	b.WriteString("      },\n")
	b.WriteString("    },\n")
	b.WriteString("  },\n")
	b.WriteString("}\n")
	return b.String()
}
